<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $date=date('Y-m-d'); $error=''; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??''; if($action==='open'){ $opening=max(0,(float)$_POST['opening_cash']); $db->prepare("INSERT INTO cash_drawer_days(business_date,opening_cash,status) VALUES(?,?,'open') ON DUPLICATE KEY UPDATE opening_cash=IF(status='open',VALUES(opening_cash),opening_cash)")->execute([$date,$opening]); audit_log('cash_drawer_opened','Opening cash Rs. '.number_format($opening,2)); $message='Cash drawer opened.';} elseif($action==='entry'){ $q=$db->prepare("SELECT * FROM cash_drawer_days WHERE business_date=? AND status='open'");$q->execute([$date]);$day=$q->fetch();if(!$day)throw new RuntimeException('Open the cash drawer first.');$amount=(float)$_POST['amount'];$reason=trim((string)$_POST['reason']);if($amount<=0||$reason==='')throw new RuntimeException('Enter a valid amount and reason.');$entryType=$_POST['entry_type']==='cash_in'?'cash_in':'cash_out';$db->prepare('INSERT INTO cash_drawer_entries(drawer_day_id,entry_type,amount,reason) VALUES(?,?,?,?)')->execute([$day['id'],$entryType,$amount,$reason]);audit_log('cash_drawer_entry',ucfirst(str_replace('_',' ',$entryType)).' Rs. '.number_format($amount,2).' · '.$reason);$message='Cash movement recorded.';} elseif($action==='close'){ $actual=max(0,(float)$_POST['closing_cash']);$q=$db->prepare("SELECT * FROM cash_drawer_days WHERE business_date=? AND status='open'");$q->execute([$date]);$day=$q->fetch();if(!$day)throw new RuntimeException('No open cash drawer for today.');$db->prepare("UPDATE cash_drawer_days SET closing_cash=?,status='closed',closed_at=NOW() WHERE id=?")->execute([$actual,$day['id']]);audit_log('cash_drawer_closed','Closing cash Rs. '.number_format($actual,2));$message='Day closed successfully.';}}catch(Throwable $e){$error=$e->getMessage();}} $q=$db->prepare('SELECT * FROM cash_drawer_days WHERE business_date=?');$q->execute([$date]);$day=$q->fetch();$entries=[];$in=$out=0;if($day){$q=$db->prepare('SELECT * FROM cash_drawer_entries WHERE drawer_day_id=? ORDER BY id DESC');$q->execute([$day['id']]);$entries=$q->fetchAll();foreach($entries as $e){if($e['entry_type']==='cash_in')$in+=(float)$e['amount'];else$out+=(float)$e['amount'];}}$expected=$day?(float)$day['opening_cash']+$in-$out:0;$actual=$day&&$day['closing_cash']!==null?(float)$day['closing_cash']:null;$difference=$actual===null?null:$actual-$expected;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cash Drawer</title><link rel="stylesheet" href="style.css"><style>.drawer{max-width:1100px;margin:auto}.drawer-hero{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.drawer-hero h1{font-size:34px;margin:4px 0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:18px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:20px;box-shadow:0 5px 18px rgba(15,23,42,.05)}.card small{color:#64748b;font-weight:700;text-transform:uppercase;font-size:11px}.card strong{display:block;font-size:25px;margin-top:8px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:20px}.panel h2{margin-top:0}.status{padding:12px 16px;border-radius:12px;background:#ecfdf5;margin-bottom:16px}.alert{margin-bottom:16px}.movement{display:grid;grid-template-columns:1fr 1fr 2fr auto;gap:10px;align-items:end}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #eef2f7;text-align:left}@media(max-width:800px){.cards,.forms{grid-template-columns:1fr 1fr}.movement{grid-template-columns:1fr}}@media(max-width:550px){.cards,.forms{grid-template-columns:1fr}.drawer-hero{display:block}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav></header><main class="drawer"><div class="drawer-hero"><div><div class="eyebrow">CASH CONTROL</div><h1>Cash Drawer</h1><p>Open, reconcile and close today's cash drawer.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($message):?><div class="status">✓ <?=e($message)?></div><?php endif;?><?php if(!$day):?><section class="panel"><h2>Open Today's Drawer</h2><p>Enter the physical cash available at the start of the day.</p><form method="post"><input type="hidden" name="action" value="open"><label>Opening Cash<input type="number" name="opening_cash" min="0" step="0.01" value="0" required></label><br><button class="btn">Open Cash Drawer</button></form></section><?php else:?><div class="cards"><div class="card"><small>Opening Cash</small><strong>Rs. <?=money((float)$day['opening_cash'])?></strong></div><div class="card"><small>Cash In</small><strong>Rs. <?=money($in)?></strong></div><div class="card"><small>Cash Out</small><strong>Rs. <?=money($out)?></strong></div><div class="card"><small>Expected Cash</small><strong>Rs. <?=money($expected)?></strong></div></div><?php if($day['status']==='open'):?><div class="forms"><section class="panel"><h2>Cash Movement</h2><form method="post" class="movement"><input type="hidden" name="action" value="entry"><select name="entry_type"><option value="cash_in">Cash In</option><option value="cash_out">Cash Out</option></select><input type="number" name="amount" min="0.01" step="0.01" placeholder="Amount" required><input name="reason" placeholder="Reason" required><button class="btn">Record</button></form></section><section class="panel"><h2>Close Day</h2><p>Count the physical cash in the drawer and enter it below.</p><form method="post"><input type="hidden" name="action" value="close"><label>Actual Cash<input type="number" name="closing_cash" min="0" step="0.01" required></label><br><button class="btn">Close Day</button></form></section></div><?php else:?><section class="panel"><h2>Day Closed ✓</h2><div class="cards"><div class="card"><small>Actual Cash</small><strong>Rs. <?=money((float)$actual)?></strong></div><div class="card"><small>Difference</small><strong><?=($difference>=0?'+':'-')?>Rs. <?=money(abs((float)$difference))?></strong></div></div></section><?php endif;?><section class="panel"><h2>Today's Cash Movements</h2><table><tr><th>Type</th><th>Amount</th><th>Reason</th><th>Time</th></tr><?php if(!$entries):?><tr><td colspan="4">No manual cash movements.</td></tr><?php else:foreach($entries as $e):?><tr><td><?=e($e['entry_type']==='cash_in'?'Cash In':'Cash Out')?></td><td>Rs. <?=money((float)$e['amount'])?></td><td><?=e($e['reason'])?></td><td><?=e($e['created_at'])?></td></tr><?php endforeach;endif;?></table></section><?php endif;?></main></body></html>